import{_ as a,o,c as i,a2 as r}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Syrolands","text":"Un laboratorio para un mundo vivo de combate","tagline":"Guía del jugador · Diseño del juego · Un mundo en desarrollo","actions":[{"theme":"brand","text":"Explora la guía","link":"/es/guide/introduction"},{"theme":"alt","text":"Explora el diseño","link":"/es/game-design/"}]},"features":[{"icon":"<svg xmlns=\\"http://www.w3.org/2000/svg\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"1.5\\" stroke-linejoin=\\"round\\" aria-hidden=\\"true\\"><path d=\\"M3 4c3-1 6 0 9 2 3-2 6-3 9-2v16c-3-1-6 0-9 2-3-2-6-3-9-2zM12 6v16\\"/></svg>","title":"Guía del jugador","details":"Comprende los sistemas de Syrolands con rapidez, estados claros y enlaces a las especificaciones completas.","link":"/es/guide/"},{"icon":"<svg xmlns=\\"http://www.w3.org/2000/svg\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"1.5\\" stroke-linejoin=\\"round\\" aria-hidden=\\"true\\"><path d=\\"M5 13V9a7 7 0 0 1 14 0v4l-3 7h-3v-6h-2v6H8zM5 10h14M12 2v5\\"/></svg>","title":"Diseño del juego","details":"Modern Combat en estado Propuesto, una alternativa Legacy y consecuencias locales significativas.","link":"/es/game-design/vision"},{"icon":"<svg xmlns=\\"http://www.w3.org/2000/svg\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"1.5\\" stroke-linejoin=\\"round\\" aria-hidden=\\"true\\"><path d=\\"m9 3-1 3-3 1-2 3 2 2-1 3 3 2 2-1 3 2 3-2 2 1 3-2-1-3 2-2-2-3-3-1-1-3z\\"/><circle cx=\\"12\\" cy=\\"11\\" r=\\"3\\"/></svg>","title":"Mundo vivo","details":"Explora las propuestas de materiales, entornos e interacciones basadas en el conocimiento.","link":"/es/game-design/living-world"},{"icon":"<svg xmlns=\\"http://www.w3.org/2000/svg\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"1.5\\" stroke-linejoin=\\"round\\" aria-hidden=\\"true\\"><path d=\\"M6 2h9l4 4v16H6zM14 2v5h5M9 11h7M9 15h7M9 19h4\\"/></svg>","title":"Magia y descubrimiento","details":"Descubre las propuestas de conocimiento de hechizos, memoria, práctica e Inscription.","link":"/es/guide/magic/overview"}]},"headers":[],"relativePath":"es/index.md","filePath":"es/index.md"}'),s={name:"es/index.md"};function n(t,e,l,d,c,u){return o(),i("div",null,[...e[0]||(e[0]=[r('<h2 id="find-your-reading-path" tabindex="-1">Elige tu recorrido <a class="header-anchor" href="#find-your-reading-path" aria-label="Enlace permanente a &quot;Elige tu recorrido&quot;">​</a></h2><p>Empieza por la <a href="/Syrolands-Public/es/guide/introduction.html">Introducción</a> y la <a href="/Syrolands-Public/es/guide/">Guía del jugador</a> para encontrar explicaciones breves, o explora el <a href="/Syrolands-Public/es/game-design/">Diseño del juego</a> para consultar reglas detalladas, propuestas y preguntas abiertas. Syrolands es un laboratorio para un mundo vivo de combate; los sistemas descritos no están necesariamente disponibles para jugar.</p><h2 id="combat-and-character" tabindex="-1">Combate y personaje <a class="header-anchor" href="#combat-and-character" aria-label="Enlace permanente a &quot;Combate y personaje&quot;">​</a></h2><p>Modern Combat es la dirección experimental preferida, todavía en estado Propuesto y pendiente de prototipos jugables. Legacy Auto-Attack sigue siendo una opción compatible de respaldo, accesibilidad y nostalgia dentro de ese diseño. Ambos conservan la resolución de resultados en el servidor; no se anuncia la disponibilidad de nuevos modos. <a href="/Syrolands-Public/es/guide/combat/overview.html">Combate</a> explora las lesiones locales junto a la salud global. <a href="/Syrolands-Public/es/guide/characters/progression.html">Progresión del personaje</a> propone personajes útiles desde el inicio, conocimiento y especialización.</p><h2 id="craft-magic-and-world" tabindex="-1">Artesanía, magia y mundo <a class="header-anchor" href="#craft-magic-and-world" aria-label="Enlace permanente a &quot;Artesanía, magia y mundo&quot;">​</a></h2><p>Las <a href="/Syrolands-Public/es/guide/professions/overview.html">Profesiones</a> conectan la aventura, el aprendizaje y la creación de objetos útiles. <a href="/Syrolands-Public/es/guide/items/item-quality.html">Calidad de los objetos</a> explora la calidad de fabricación y las pérdidas significativas de equipo. <a href="/Syrolands-Public/es/guide/magic/overview.html">Magia</a> propone descubrimiento, conocimiento de hechizos, memoria y práctica. <a href="/Syrolands-Public/es/game-design/living-world.html">Mundo vivo</a> explora interacciones ambientales y materiales.</p><h2 id="reading-feature-status" tabindex="-1">Cómo interpretar los estados <a class="header-anchor" href="#reading-feature-status" aria-label="Enlace permanente a &quot;Cómo interpretar los estados&quot;">​</a></h2><p><strong>Aceptado</strong> significa una intención de diseño aprobada; <strong>Experimental</strong> identifica un experimento delimitado. <strong>Propuesto</strong> indica mecánicas candidatas y <strong>Sin resolver</strong>, preguntas abiertas. <strong>Implementado</strong> describe código existente dentro del alcance indicado, sin prometer disponibilidad actual ni equilibrio validado. <strong>Obsoleto</strong> marca orientación que ha sido sustituida. Cada página conserva estas distinciones.</p><h2 id="explore-the-design" tabindex="-1">Explora el diseño <a class="header-anchor" href="#explore-the-design" aria-label="Enlace permanente a &quot;Explora el diseño&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/vision.html">Visión del proyecto</a> · <a href="/Syrolands-Public/es/guide/characters/progression.html">Personajes</a> · <a href="/Syrolands-Public/es/guide/combat/overview.html">Combate</a> · <a href="/Syrolands-Public/es/guide/magic/overview.html">Magia</a> · <a href="/Syrolands-Public/es/guide/professions/overview.html">Profesiones</a> · <a href="/Syrolands-Public/es/guide/items/item-quality.html">Objetos</a></p>',10)])])}const g=a(s,[["render",n]]);export{m as __pageData,g as default};
